"""Curated extraction from actually read methods/results, separate from abstract leads."""
from prepare import T,read,dump,now

def main():
 online={r['doi'].lower():r for r in read(T/'online_records.json') if r.get('doi')}
 pm={r['seed_key']:r for r in read(T/'seed_pubmed_results.json')}
