 rows=[
 {'doi':'10.1128/aem.00563-24','depth':'全文方法、结果与讨论；已读图1–4图注，未播放补充视频或复核附件原图','system':'食品工业废水UASB厌氧颗粒；固定、脱水、Os染色、环氧包埋','temperature':'制样4°C/室温，树脂140°C聚合；不是原位活体温度','size':'颗粒直径本轮未核明；3条截取柱段用于孔洞分析，不视为3个独立生物重复','methods':'SPring-8 BL47XU双能量L3-edge subtraction μCT；Os 10.86/10.87 keV；1800投影、200 ms；ImageJ/Fiji分割','spatial_scale':'原始pixel/voxel 0.1988 µm（198.8 nm）；3D viewer 0.7952 µm；体素大小不等同经独立验证的空间分辨率','finding':'真正的三维孔洞重建；Os显影包含微生物和EPS；gold-ISH虽标记但未产生可检测CT对比，不能声称定位到特定菌群','quantitative':'截面平均孔洞面积3.8±0.67至42±8.7 µm²；截面面积占比0.29±0.11%至12±4.2%，随深度变化（n=3柱段）','measurement_class':'图像实测/分割统计；不是有效扩散系数或流速','boundary':'未观察到连接孔洞的通道；小通道可低于体素尺度，故不能断言不存在通道。不能区分孔中水、气或其他轻元素物质；固定包埋结构不等于活体灌流；气体释放/浮泥是解释，非直接通量测量','applicability':'为微曝气AD提供三维几何和成像局限依据，不给O2实际穿透或耐氧阈值','locator':'PMC11337819 #s2 Results and discussion / Three-dimensional internal structure；Fig3；#s3 Methods / SR X-ray μCT scanning and image analysis','source_path':ft['S01']['raw_path'],'sections_path':'evidence/S01_body_sections.json','true_whole_aggregate_3D_verified':True},
 {'doi':'10.1128/aem.01426-07','depth':'全文方法、结果、讨论；Fig3–6图注；未重新读取补充标定原图','system':'脱脂乳合成进水、实验室UASB；FISH固定20 µm切片；活性剖面与氯仿失活扩散试验分开','temperature':'UASB、微剖面和扩散试验均35°C','size':'微传感器/扩散实验选择直径约2 mm颗粒；流动池4 L，液速约5 mm/s','methods':'H2极谱微电极：tip约10 µm、t90<2 s、检出限约1 µM；CH4生物传感器tip50–100 µm、t90约200 s、300 µm步长；ORP相对Ag/AgCl；Deff用失活颗粒中心H2瞬态与模型拟合','spatial_scale':'FISH为20 µm厚切片CLSM；不是完整颗粒三维重建。不同化学种剖面在不同颗粒上测，非同一颗粒逐像素共注册','finding':'外层约250 µm以细菌为主，内层古菌较多；>400 µm信号弱。H2生成在100 µm附近、消耗及CH4生成更深。12 mM NaHCO3下H2降至检出限1 µM以下；无NaHCO3时约100 µm处峰26 µM','quantitative':'Deff,H2=(2.66±0.13)×10^-5 cm²/s（n=3），为35°C水中Dw的57±3%；CH4净生成峰11.5±3.9 µmol cm^-3 h^-1；表面H2净释放2.3±4.3 µmol cm^-2 h^-1','measurement_class':'浓度剖面实测；Deff为无反应失活颗粒瞬态拟合（相关系数0.98）；生成/释放速率由Fick模型反演','boundary':'颗粒纯氯仿失活10 min后冲洗，非活性颗粒净扩散反应系数。CH4有效扩散系数假设沿用H2相对水比57%，非独立测量。CH4探头可能压缩颗粒；不能以H2定位直接指定所有产氢菌/氢营养古菌功能','applicability':'提供聚集体内扩散及空间反应的直接AD证据；H2系数不能直接赋给O2/CO2或其他污泥；无O2微剖面/氧反馈实验','locator':'PMC2168234 #sec1 Methods: Microsensor measurements, Estimation of Deff；#sec12 Results Fig3–6；#sec17 Discussion','source_path':ft['S02']['raw_path'],'sections_path':'evidence/S02_body_sections.json','true_whole_aggregate_3D_verified':False},
 {'doi':'10.1128/aem.68.9.4247-4252.2002','depth':'全文方法、结果及讨论；Tables1–3与Fig1图注','system':'Syntrophobacter fumaroxidans–Methanospirillum hungatei丙酸互营共培养，不是整座AD反应器','temperature':'常规培养和酶测37°C；H2监测再悬浮培养30°C','size':'多数细胞悬浮；取样即易破坏的弱聚集。10 µm扩散距离为模型假设，非图像距离实测','methods':'Percoll双次分离（显微污染<1%）；氢化酶/甲酸脱氢酶及重组培养；GC与还原气分析器测H2；Fick估算电子载体扩散','spatial_scale':'菌间模型，非颗粒/絮体间三维通量图','finding':'合成培养FDH活性升高、重组培养速率与FDH相关，支持甲酸为主要载体；H2转移未被排除','quantitative':'H2约19–21 nM（2.5–2.7 Pa，30°C）；以2.5e8 cells/ml、假设平均距离10 µm、表面H2=21/52 nM估算H2通量2.5 nmol ml^-1 min^-1；另一浓度情景0.3；产乙酸对应H2当量18.6','measurement_class':'气体/酶活/培养表现为实测；2.5、0.3与18.6为不同输入/当量计算，非直接测得菌间通量','boundary':'不把10 µm写成实测菌间距。细胞表面浓度取文献假设；未计弱絮凝。结果不能证明所有互营均以甲酸为主，也不是DIET证据','applicability':'给微曝气AD解释互营受限时需同时考虑H2/甲酸、温度与细胞结构的边界；未研究氧暴露','locator':'PMC124120 Methods/Organisms and cultivation；Results/Growth and Tables1–3；Discussion末段Fick计算','source_path':next(r['raw_path'] for r in read(T/'selected_fulltext_retrieval.json') if r['id']=='SG-28F1C544B55F'),'sections_path':'evidence/SG-28F1C544B55F_body_sections.json','true_whole_aggregate_3D_verified':False}]
